    void labelLongPress(View view,Runnable show){
        boolean[] active={false},pending={false},moved={false};long[] down={0};float[] point={0,0};int slop=android.view.ViewConfiguration.get(a).getScaledTouchSlop();
        view.setOnLongClickListener(v->{if(active[0])pending[0]=true;else v.post(show);return true;});
        view.setOnTouchListener((v,event)->{
            if(event.getActionMasked()==android.view.MotionEvent.ACTION_DOWN){active[0]=true;pending[0]=false;moved[0]=false;down[0]=event.getEventTime();point[0]=event.getX();point[1]=event.getY();}
            if(event.getActionMasked()==android.view.MotionEvent.ACTION_MOVE&&(Math.abs(event.getX()-point[0])>slop||Math.abs(event.getY()-point[1])>slop))moved[0]=true;
            if(event.getActionMasked()==android.view.MotionEvent.ACTION_UP){active[0]=false;boolean held=!moved[0]&&(pending[0]||event.getEventTime()-down[0]>=android.view.ViewConfiguration.getLongPressTimeout());if(held){v.cancelLongPress();v.setPressed(false);v.post(show);return true;}}
            if(event.getActionMasked()==android.view.MotionEvent.ACTION_CANCEL){active[0]=false;pending[0]=false;}
            return false;
        });
    }
