        EditText note=a.field(f,"备注（可选）",e==null?"":e.optString("note"));List<String> tags=tagPicker(f,e,false);String[] deadline={e==null?"":e.optString("deadline")};LinearLayout ddlRow=a.row();TextView ddl=a.action(deadline[0].isEmpty()?"设置 DDL（可选）":"DDL "+deadline[0],()->{});ddl.setTextSize(15);ddl.setOnClickListener(v->a.pickDate(deadline[0].isEmpty()?date[0]:LocalDate.parse(deadline[0]),d->{deadline[0]=d.toString();ddl.setText("DDL "+deadline[0]);}));ddlRow.addView(ddl,new LinearLayout.LayoutParams(0,a.dp(48),1));ddlRow.addView(a.action("清除",()->{deadline[0]="";ddl.setText("设置 DDL（可选）");}));f.addView(ddlRow);
